package com.netmoni.server.service;
import java.util.*;
import java.time.Instant;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.netmoni.server.dto.agent.AgentNetworkRequest;
import com.netmoni.server.dto.discovery.AgentNetworkResponse;
import com.netmoni.server.entity.*;
import com.netmoni.server.repository.*;
@Service
public class AgentNetworkService {
 private final AgentNetworkRepository networks;private final AgentRepository agents;private final DeviceRepository devices;private final DiscoveryScanRepository scans;private final NetMoniEventPublisher events;
 public AgentNetworkService(AgentNetworkRepository networks,AgentRepository agents,DeviceRepository devices,DiscoveryScanRepository scans,NetMoniEventPublisher events){this.networks=networks;this.agents=agents;this.devices=devices;this.scans=scans;this.events=events;}
 @Transactional public void synchronize(UUID agentId,List<AgentNetworkRequest> reported){Agent a=agents.findById(agentId).orElseThrow(()->new AgentNotFoundException(agentId));if(reported==null)reported=List.of();if(reported.size()>64)throw new IllegalArgumentException("At most 64 interface networks can be reported");Set<String> seen=new HashSet<>();for(var r:reported){validate(r);String key=r.interfaceName()+"|"+r.cidr();if(!seen.add(key))continue;boolean allowed=a.getAuthorizedCidrs().stream().anyMatch(c->containsCidr(c,r.cidr()));boolean eligible=allowed&&r.scanEligible()&&"UP".equalsIgnoreCase(r.interfaceStatus());boolean created=networks.findByAgent_IdAndInterfaceNameAndCidr(agentId,r.interfaceName(),r.cidr()).isEmpty();var row=networks.findByAgent_IdAndInterfaceNameAndCidr(agentId,r.interfaceName(),r.cidr()).orElseGet(()->new AgentNetwork(null,a,r.interfaceName(),r.displayName(),r.interfaceType(),r.interfaceStatus(),r.address(),r.cidr(),r.subnetMask(),r.broadcastAddress(),r.gateway(),r.macAddress(),r.ipv6Address(),r.ipv6PrefixLength(),false,false,Instant.now()));row.update(r.interfaceName(),clean(r.displayName(),200),safe(r.interfaceType(),30,"OTHER"),safe(r.interfaceStatus(),20,"UNKNOWN"),clean(r.address(),45),r.cidr(),clean(r.subnetMask(),45),clean(r.broadcastAddress(),45),clean(r.gateway(),45),validMac(r.macAddress())?r.macAddress():null,clean(r.ipv6Address(),80),r.ipv6PrefixLength(),allowed,eligible,r.lastDetectedAt());networks.save(row);events.publish("/topic/networks",created?"network.discovered":"network.updated",response(row));}for(AgentNetwork row:networks.findByAgent_Id(agentId)){if(!seen.contains(row.getInterfaceName()+"|"+row.getCidr())&&row.markUnavailable()){networks.save(row);events.publish("/topic/networks","network.updated",response(row));}}}
 @Transactional(readOnly=true) public List<AgentNetworkResponse> all(){return networks.findAll().stream().map(this::response).toList();}
 @Transactional(readOnly=true) public List<AgentNetworkResponse> byAgent(UUID id){if(!agents.existsById(id))throw new AgentNotFoundException(id);return networks.findByAgent_Id(id).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public AgentNetwork requireEligible(UUID agentId,UUID networkId){var n=networks.findByIdAndAgent_Id(networkId,agentId).orElseThrow(()->new IllegalArgumentException("Network does not belong to this agent"));if(!n.isAuthorized()||!n.isScanEligible()||n.getAgent().getStatus()!=AgentStatus.ONLINE)throw new IllegalStateException("Network or agent is not eligible for scanning");return n;}
 @Transactional(readOnly=true) public boolean isAuthorizedRange(Agent agent,String cidr){return agent.getAuthorizedCidrs().stream().anyMatch(allowed->containsCidr(allowed,cidr));}
 private static void validate(AgentNetworkRequest r){if(r==null||r.interfaceName()==null||r.interfaceName().isBlank()||r.cidr()==null||!r.cidr().matches("(?:\\d{1,3}\\.){3}\\d{1,3}/\\d{1,2}"))throw new IllegalArgumentException("Network interface and IPv4 CIDR are required");if(r.interfaceName().length()>120||r.cidr().length()>50)throw new IllegalArgumentException("Interface fields exceed maximum length");String[] p=r.cidr().split("[/\\.]",-1);for(int i=0;i<4;i++)if(Integer.parseInt(p[i])>255)throw new IllegalArgumentException("Invalid network CIDR");int prefix=Integer.parseInt(p[4]);if(prefix>32)throw new IllegalArgumentException("Invalid network prefix");if(r.address()==null||r.address().isBlank()||!containsCidr(r.cidr(),r.address()+"/32"))throw new IllegalArgumentException("Interface IPv4 address must belong to its reported CIDR");if(r.ipv6PrefixLength()!=null&&(r.ipv6PrefixLength()<0||r.ipv6PrefixLength()>128))throw new IllegalArgumentException("Invalid IPv6 network prefix");}
 private static boolean containsCidr(String outer,String inner){try{String[] a=outer.split("/"),b=inner.split("/");int ap=Integer.parseInt(a[1]),bp=Integer.parseInt(b[1]);return ap<=bp&&mask(ip(a[0]),ap)==mask(ip(b[0]),ap);}catch(RuntimeException e){return false;}}
 private static long ip(String value){long n=0;for(String s:value.split("\\.")){int x=Integer.parseInt(s);if(x<0||x>255)throw new IllegalArgumentException();n=(n<<8)|x;}return n;}
 private static long mask(long n,int p){long m=p==0?0:(0xffff_ffffL<<(32-p))&0xffff_ffffL;return n&m;}
 private static String clean(String s,int n){return s==null||s.isBlank()?null:s.substring(0,Math.min(n,s.length())).trim();}
 private static String safe(String s,int n,String fallback){String v=clean(s,n);return v==null?fallback:v;}
 private boolean validMac(String mac){return mac!=null&&mac.matches("(?i)(?:[0-9a-f]{2}:){5}[0-9a-f]{2}");}
 private AgentNetworkResponse response(AgentNetwork n){return AgentNetworkResponse.from(n,(int)devices.countByAgent_IdAndNetworkCidr(n.getAgent().getId(),n.getCidr()),scans.findFirstByNetworkIdOrderByCreatedAtDesc(n.getId()).map(com.netmoni.server.entity.DiscoveryScan::getFinishedAt).orElse(null));}
}
